var metrics = await myboticaReviewTab.playwright.evaluate(() => {
  const slides = [...document.querySelectorAll('.slide')];
  const selector = 'h1,h2,h3,p,.page,.stamp,.teacher-note,.lesson-note,.scribble,.helper-side-note,.graduate-cta,.no,img';
  const rect = el => { const r=el.getBoundingClientRect(); return {x:+r.x.toFixed(1),y:+r.y.toFixed(1),w:+r.width.toFixed(1),h:+r.height.toFixed(1),right:+r.right.toFixed(1),bottom:+r.bottom.toFixed(1)}; };
  const selected = slides.map((s,i)=>{
    const sr=s.getBoundingClientRect();
    const elements=[...s.querySelectorAll(selector)].filter(el=>getComputedStyle(el).display!=='none').map(el=>{
      const r=el.getBoundingClientRect();
      const overflow={left:+Math.max(0,sr.left-r.left).toFixed(1),right:+Math.max(0,r.right-sr.right).toFixed(1),top:+Math.max(0,sr.top-r.top).toFixed(1),bottom:+Math.max(0,r.bottom-sr.bottom).toFixed(1)};
      return {tag:el.tagName.toLowerCase(),cls:el.className||'',text:(el.innerText||el.alt||'').trim().replace(/\s+/g,' ').slice(0,90),rect:rect(el),overflow,client:[el.clientWidth,el.clientHeight],scroll:[el.scrollWidth,el.scrollHeight]};
    });
    const clipped=elements.filter(e=>e.scroll[0]>e.client[0]+1||e.scroll[1]>e.client[1]+1);
    const out=elements.filter(e=>Object.values(e.overflow).some(v=>v>1));
    return {index:i+1,slideRect:rect(s),client:[s.clientWidth,s.clientHeight],scroll:[s.scrollWidth,s.scrollHeight],clipped,out,elements};
  });
  return {
    readyState:document.readyState,
    fontStatus:document.fonts.status,
    golos:document.fonts.check('29px Golos'),
    unbounded:document.fonts.check('58px Unbounded'),
    slides:slides.length,
    images:[...document.images].map(img=>({src:img.getAttribute('src'),complete:img.complete,natural:[img.naturalWidth,img.naturalHeight],display:getComputedStyle(img).display})),
    viewport:[innerWidth,innerHeight],
    documentSize:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],
    selected
  };
});
nodeRepl.write(JSON.stringify({
  readyState:metrics.readyState,fontStatus:metrics.fontStatus,golos:metrics.golos,unbounded:metrics.unbounded,slides:metrics.slides,viewport:metrics.viewport,documentSize:metrics.documentSize,
  brokenImages:metrics.images.filter(x=>!x.complete||!x.natural[0]),
  slideSummary:metrics.selected.map(s=>({index:s.index,slideRect:s.slideRect,client:s.client,scroll:s.scroll,clipped:s.clipped.map(x=>({tag:x.tag,cls:x.cls,text:x.text,client:x.client,scroll:x.scroll})),out:s.out.map(x=>({tag:x.tag,cls:x.cls,text:x.text,overflow:x.overflow,rect:x.rect}))}))
},null,2));

